import json
CFG = json.loads('{"ok_msg":"The transfer is done. Tell the customer you are connecting them now, thank them, say goodbye and call the closing tool.","fail_msg":"The transfer did NOT work. Never say they are being transferred. Call it once more with the same queue; if it fails again, tell the customer and continue."}')

def tv(x):
    return x is True or str(x).strip().lower() == 'true'
def failed(res):
    if not isinstance(res, dict):
        return True
    sc = res.get('status_code')
    if sc is not None and str(sc) != '200':
        return True
    return not isinstance(res.get('data'), dict)
def tell(result, msg):
    if isinstance(result.get('data'), dict):
        result['data']['what_to_do_next'] = msg
    else:
        result['what_to_do_next'] = msg

try:
    if isinstance(result, dict):
        result.pop('header', None)
        ok = (not failed(result)) and tv(result['data'].get('ok'))
        tell(result, str(CFG.get('ok_msg') or '') if ok else str(CFG.get('fail_msg') or ''))
except Exception:
    pass

