e","late_days":"days_late"},"types":{"credit_card":{"spoken":"credit card ending {card_last4}","floor_field":"minimum_payment"},"personal_loan":{"spoken":"personal loan","floor_field":"instalment_amount"},"car_loan":{"spoken":"car loan","floor_field":"instalment_amount"} },"response_path":"products"},"debt_statement":"I am calling from the collections team about a late payment","first_ask":"Can you make this payment today?","persuasion":{"attempts":[{"amount":"full_or_floor_if_too_much","date":"last_business_day_this_week_or_next_if_today"},{"amount":"floor","date":"deadline"}],"floor_offer":{"once":true,"say_with_offer":"the rest stays overdue"},"close_refused":["no_promise","refused"]},"callback":{"days":["today","next_business_day"],"from":"10:00","to":"19:00","later_than_now":true,"ask_again_once":true,"close_booked":["not_reached","callback"],"close_none":["not_reached","no_callback"]},"third_party":{"wrong_number":["not_reached","wrong_number"],"deceased":{"say":"I am sorry for your loss.","close":["not_reached","deceased"]} },"special_cases":[{"name":"hardship","trigger":"the customer mentions illness, a death in the family or job loss","precedence":1,"action":"say one short sentence of sympathy, make no persuasion attempt, offer to connect them with the customer support team. If the customer still names a date or an amount themselves, record the promise under the normal date and amount rules.","line":"I am sorry to hear that. Would you like me to connect you with our customer support team?","accept":{"transfer":"support","close":["transferred","support"]},"decline":{"close":["no_promise","hardship"]} },{"name":"already_paid","trigger":"the customer says they already paid this past-due amount","action":"say that payments can take one business day to appear, take no promise","close":["paid"],"precedence":3},{"name":"dispute","trigger":"the customer says the debt is not theirs, they never had this product, or the product was closed or paid off in the past","action":"do not argue and do not take a promise","close":["no_promise","dispute"],"precedence":4},{"name":"restructuring","trigger":"the customer asks for a new payment plan or lower instalments","action":"do not describe a plan; transfer","transfer":"restructuring","close":["transferred","restructuring"],"precedence":5},{"name":"human","trigger":"the customer asks for a human","precedence":2,"action":"ask once whether you can help first; if they insist, transfer","transfer":"general","close":["transferred","human"]},{"name":"no_talk","trigger":"the customer says twice that they do not want to talk","action":"close; before identity is verified close as not_verified / declined instead","close":["no_promise","refused"],"precedence":6}],"outcome_logic":{"on_transfer":"transferred","reason_by_queue":{"support":"support","restructuring":"restructuring","general":"human"},"on_promise":"promise","no_deal":"no_promise","verify_failed":["not_verified","failed"],"promise_failed":["no_promise","service_error"]},"notes":{"used":false},"sentences":{"after_promise":"You will receive a text message confirming this promise."},"read_back":{"ask":"Do you confirm?"},"robot_question":"Say that you are Freya Bank\'s digital assistant and continue.","scam_question":"Say they can verify the call by phoning Freya Bank\'s customer service number, and continue.","never_offer":["a discount","a waiver","an instalment plan","any term that is not in the brief"],"restricted_words":{"recorded":"say the promise is recorded only after create_promise returns ok true"},"tool_names":{"verify":"verify_identity","account":"get_account","promise":"create_promise","callback":"schedule_callback","transfer":"transfer_to_agent","note":"add_note","close":"close_call"},"tool_fields":{"customer":"customer_id","product":"product_id","amount":"amount","date":"date","queue":"queue","note_reason":"reason","outcome":"outcome","reason":"reason"},"tool_failures":{"create_promise":"retry once, then say it could not be done and close no_promise / service_error","other":"gap: brief says nothing; API says the call may be repeated"},"gaps":["tool failure handling for tools other than create_promise","customer service phone number not given"]}')

def date_expr(expr, today, deadline=None):
    e = str(expr or '')
    if e == 'today':
        return today
    if e == 'next_business_day':
        return nextbiz(today)
    if e == 'deadline':
        return deadline or today
    if e.startswith('business_days_after_today:'):
        return nth_biz_after(today, int(e.split(':')[1]))
    if e.startswith('calendar_days_after_today:'):
        bits = e.split(':')
        d = today + TD(days=int(bits[1]))
        how = bits[2] if len(bits) > 2 else ''
        while how in ('back', 'forward') and not isbiz(d):
            d = d + TD(days=-1 if how == 'back' else 1)
        return d
    if e in ('last_business_day_this_week', 'last_business_day_this_week_or_next_if_today'):
        d = week_end_biz(today)
        if d is None or d < today or (d == today and e.endswith('_if_today')):
            d = week_end_biz(today + TD(days=7))
        if deadline and d and d > deadline:
            d = deadline
        return d or today
    return today
def band_for(late):
    for b in SPEC.get('bands') or []:
        if int(b.get('min_days', 0)) <= late <= int(b.get('max_days', 10 ** 6)):
            return b
    return None
def week_table(today):
    rows = ['- today = ' + sp(today) + ' (' + today.isoformat() + ')',
            '- tomorrow = ' + sp(today + TD(days=1)) + ' (' + (today + TD(days=1)).isoformat() + ')']
    for i in range(7):
        t, n = this_weekday(today, i), next_weekday(today, i)
        rows.append('- "this ' + DN[i] + '" = ' + sp(t) + ('  (in the past)' if t < today else '') + '; "next ' + DN[i] + '" = ' + sp(n))
    return '\n'.join(rows)
def calendar_lines(today, deadline, days_after=21):
    rows, x = [], today
    while x <= deadline + TD(days=days_after):
        tag = sp(x) + ' (' + x.isoformat() + ')' + (' [today]' if x == today else '')
        if x > deadline:
            act = ('AFTER the deadline. Say: "The latest date I can record is ' + sp(deadline) + '. Can you pay on that day?" '
                   'If they say yes, ' + sp(deadline) + ' is the agreed date: do not ask for another day.')
        elif isbiz(x):
            act = 'OK, can be recorded.'
        else:
            why = 'a bank holiday' if x.isoformat() in HOL else 'not a business day'
            nb = nextbiz(x)
            act = ('NOT allowed, ' + why + '. Offer the next business day, ' + sp(nb) + '.') if nb <= deadline else (
                  'NOT allowed, ' + why + ', and the next business day is after the deadline. Offer ' + sp(deadline) + '.')
        rows.append('- ' + tag + ': ' + act)
        x = x + TD(days=1)
    return '\n'.join(rows)
def callback_text(today, hm):
    cb = SPEC.get('callback') or dict()
    lo, hi = cb.get('from', ''), cb.get('to', '')
    rows = []
    for day in cb.get('days') or []:
        d = date_expr(day, today)
        if d == today and cb.get('later_than_now'):
            if hi and hm >= hi:
                rows.append('- Today is no longer possible: it is after ' + hi + '.')
                continue
            start = 'from ' + lo if (lo and hm < lo) else 'any time later than ' + hm
            rows.append('- Today, ' + sp(d) + ' (' + d.isoformat() + '): ' + start + ' up to ' + hi + ' included.')
        else:
            rows.append('- ' + sp(d) + ' (' + d.isoformat() + '): from ' + lo + ' to ' + hi + ', both included.')
    rows.append('- Every other day, and every other time, is OUTSIDE the window.')
    return '\n'.join(rows)
try:
    now = str(vars.get(SPEC.get('now_variable') or 'now') or '')
    today = D.fromisoformat(now[:10])
    hm = now[11:16] if len(now) >= 16 else '00:00'
