    return d.weekday() not in WEEKEND and d.isoformat() not in HOL
def sp(d):
    return DN[d.weekday()] + ' ' + str(d.day) + ' ' + MN[d.month - 1] + ' ' + str(d.year)
def nextbiz(d):
    x = d + TD(days=1)
    for _ in range(400):
        if isbiz(x):
            return x
        x = x + TD(days=1)
    return x
def nth_biz_after(d, n):
    x = d
    k = 1 if (CAL.get('count_today') and isbiz(d)) else 0
    for _ in range(400):
        if k >= n:
            return x
        x = x + TD(days=1)
        if isbiz(x):
            k += 1
    return x
