HOL = set(CAL.get('holidays') or [])
WEEKEND = set(CAL.get('weekend') if CAL.get('weekend') is not None else [5, 6])
DN = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MN = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
D = datetime.date
TD = datetime.timedelta
def isbiz(d):
    return d.weekday() not in WEEKEND and d.isoformat() not in HOL
def sp(d):
    return DN[d.weekday()] + ' ' + str(d.day) + ' ' + MN[d.month - 1] + ' ' + str(d.year)
def nextbiz(d):
    x = d + TD(days=1)
    for _ in range(400):
        if isbiz(x):
            return x
        x = x + TD(days=1)
    return x
def nth_biz_after(d, n):
    x = d
    k = 1 if (CAL.get('count_today') and isbiz(d)) else 0
    for _ in range(400):
        if k >= n:
            return x
        x = x + TD(days=1)
        if isbiz(x):
            k += 1
    return x
def week_end_biz(d):
    """Last business day of d's calendar week (Monday to Sunday), or None if there is none."""
    monday = d - TD(days=d.weekday())
    x = monday + TD(days=6)
    while x >= monday:
        if isbiz(x):
            return x
        x = x - TD(days=1)
    return None
def this_weekday(today, i):
    return today - TD(days=today.weekday()) + TD(days=i)
def next_weekday(today, i):
    return this_weekday(today, i) + TD(days=7)

import json
try:
    p = params if isinstance(params, dict) else dict()
except Exception:
    p = dict()
try:
    k = str(p.get('product_number') or '').strip()
    amt = float(str(p.get('amount')).replace(',', ''))
    d = str(p.get('date') or '')[:10]
    day = D.fromisoformat(d)
    items = [a for a in json.loads(str(vars.get('agreements_json') or '[]')) if str(a.get('n')) != k]
    items.append(dict(n=k, words=str(vars.get('p' + k + '_words_id') or ('product ' + k)), amount='%.2f' % amt, date=d, spoken=sp(day)))
    items.sort(key=lambda a: int(a['n']))
    vars['agreements_json'] = json.dumps(items)
    vars['agreements_text'] = '\n'.join('- product ' + a['n'] + ', ' + a['words'] + ': ' + a['amount'] + ' on ' + a['spoken'] + ' (' + a['date'] + ')' for a in items)
